// Fuehrt alle Seiten zusammen und prueft, ob die Liste vollstaendig ist. Bei Zweifel Abbruch mit Fehler,
// damit kein aufrufender Workflow mit einer unvollstaendigen Liste weiterarbeitet (z.B. faelschlich archiviert).
const liste = $('Start durch Workflow').first().json.liste;
if (!['kunden', 'projekte'].includes(liste)) throw new Error('Unbekannte Liste: ' + liste);
const seiten = $input.all().map(i => i.json || {});
if (!seiten.length || seiten.some(s => !Array.isArray(s.entries))) throw new Error('Papierkram-Liste ' + liste + ' fehlerhaft abgerufen.');
if (seiten[seiten.length - 1].has_more) throw new Error('Papierkram-Liste ' + liste + ' nicht vollständig (weitere Seiten vorhanden).');
const gesehen = new Set();
const eintraege = [];
for (const s of seiten) for (const e of s.entries) { if (!gesehen.has(e.id)) { gesehen.add(e.id); eintraege.push(e); } }
const gesamt = Number(seiten[0].total_entries);
if (Number.isFinite(gesamt) && eintraege.length !== gesamt) throw new Error('Papierkram-Liste ' + liste + ' unvollständig: ' + eintraege.length + ' von ' + gesamt + ' Einträgen.');
return [{ json: { liste, anzahl: eintraege.length, eintraege } }];
